def lps(s):
    n = len(s)
    # Create a DP table to store the lengths of longest palindromic subsequence,
    # initialized with 0
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Fill the table by considering substrings of length 2 to n
    for length in range(2, n + 1):
        for i in range(0, n - length + 1):
            j = i + length - 1

            # If the substring begins and ends with the same character
            if s[i] == s[j]:
                if length == 2:
                    dp[i][j] = 2
                else:
                    dp[i][j] = 2 + dp[i + 1][j - 1]

            # If the substring begins or ends with different characters
            else:
                dp[i][j] = max(dp[i][j - 1], dp[i + 1][j])

    return dp[0][n-1] if n > 0 else 0
