        else:
            g, y, x = extended_gcd(b % a, a)
            return (g, x - (b // a) * y, y)

    _, x0, y0 = extended_gcd(a, b)

    # x and y can be found as follows:
    # First solution: x = x0 * (n / gcd), y = (n / gcd) - a * x / b
    x = x0 * (n // gcd) % (b // gcd)
    if x < 0:  # Make sure x is positive
        x += (b // gcd)
    y = (n - a * x) // b

    # Return positive values only
    if x >= 0 and y >= 0:
        return (x, y)
    elif (y % (b // gcd)) >= 0 and (a * (-y) % gcd) == x:
        return (-y, x)

    return None
