def eulerian_num(n, m):
    """Return the Eulerian number a(n, m).

    Eulerian numbers count the number of permutations of {1, ..., n} such that
    there are exactly m cycles in the permutation when read in a circular fashion.
    """
    if n == 0:
        return 1 if m == 1 else 0
    # Using the recurrence relation for Eulerian numbers:
    # a(n, m) = (n - m) * a(n - 1, m - 1) + (m + 1) * a(n - 1, m)
    if m == 0:
        return 0
    a_prev_prev = [0] * (m + 1)  # Placeholder for unused previous values
    a_prev = [0] * (m + 1)
    a_current = [0] * (m + 1)

    a_prev[0] = 1  # Base case

    for i in range(1, n + 1):
        # Compute new value of a_current[m]
        for j in range(m + 1):
            if j == 0:
                if i == 1:
                    a_current[j] = 1
                else:
                    a_current[j] = (i - 1) * a_prev[j]
            else:
                if i > j:
                    a_current[j] = ((i - j) * a_prev[j - 1]) + ((j + 1) * a_prev[j])
                else:
                    a_current[j] = 0

        # Update previous state before moving to the next iteration
        a_prev_prev, a_prev = a_prev, a_current
        a_current = [0] * (m + 1)

    return a_prev[m]
